import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from '../src/totals.js';

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }), 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 5000 }), 50000);
});

test('lineDiscount calculates discount amount', () => {
  const line = { qty: 5, unitPrice: 100, discountPercent: 10 };
  const total = 500;
  const discount = 50;
  assert.equal(lineDiscount(line), discount);
});

test('lineDiscount applies bulk discount (2.5%) when qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10 };
  const total = 1000;
  const firstDiscount = 100;
  const afterFirstDiscount = 900;
  const bulkDiscount = 22.5;
  const expected = 122.5;
  assert.equal(lineDiscount(line), expected);
});

test('lineDiscount defaults to 0% line discount but applies bulk discount if qty >= 10', () => {
  const line = { qty: 10, unitPrice: 100 };
  const total = 1000;
  const bulkDiscount = 25;
  assert.equal(lineDiscount(line), bulkDiscount);
});

test('lineDiscount returns 0 with qty < 10 and no explicit discount', () => {
  const line = { qty: 5, unitPrice: 100 };
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount clamps negative discounts to 0, applies bulk to full amount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: -5 };
  const total = 1000;
  const firstDiscount = 0;
  const afterFirstDiscount = 1000;
  const bulkDiscount = 25;
  assert.equal(lineDiscount(line), 25);
});

test('lineDiscount handles various percentages with bulk discount', () => {
  const line10 = { qty: 10, unitPrice: 500 };
  const line20 = { qty: 20, unitPrice: 500 };

  assert.equal(lineDiscount({ ...line10, discountPercent: 0 }), 125);
  assert.equal(lineDiscount({ ...line20, discountPercent: 0 }), 250);

  const result50 = lineDiscount({ ...line10, discountPercent: 50 });
  const expected50 = 2500 + 1250;
  assert.equal(result50, expected50);
});

test('lineDiscount with qty exactly 10 applies bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 5 };
  const total = 1000;
  const firstDiscount = 50;
  const afterFirstDiscount = 950;
  const bulkDiscount = 23.75;
  const expected = 73.75;
  assert.equal(lineDiscount(line), expected);
});

test('lineDiscount with qty 9 does not apply bulk discount', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 5 };
  const total = 900;
  const firstDiscount = 45;
  assert.equal(lineDiscount(line), firstDiscount);
});

test('lineDiscount with qty 11 applies bulk discount', () => {
  const line = { qty: 11, unitPrice: 100, discountPercent: 5 };
  const total = 1100;
  const firstDiscount = 55;
  const afterFirstDiscount = 1045;
  const bulkDiscount = 26.125;
  const expected = 81.125;
  assert.equal(lineDiscount(line), expected);
});

test('lineVAT calculates VAT on amount after discount', () => {
  const line = { qty: 100, unitPrice: 100, discountPercent: 10, vatRate: 20 };
  const total = 10000;
  const discount = 1000;
  const base = total - discount;
  const expectedVat = Math.round(base * 0.2 * 1e6) / 1e6;
  assert.equal(lineVAT(line), expectedVat);
});

test('lineVAT defaults to 0% if not specified', () => {
  const line = { qty: 100, unitPrice: 100 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT rounds to nearest cent using banker\'s rounding', () => {
  const line = { qty: 3, unitPrice: 100, vatRate: 23 };
  const vat = lineVAT(line);
  assert.equal(vat, Math.round(300 * 0.23 * 1e6) / 1e6);
});

test('lineVAT with discount and VAT', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 15, vatRate: 19 };
  const vat = lineVAT(line);
  const expectedBase = 10000 - 1500;
  const expectedVat = Math.round(expectedBase * 0.19 * 1e6) / 1e6;
  assert.equal(vat, expectedVat);
});

